import{c as e,J as l,h as a,k as r}from"./chunks/framework.WgZQdPFo.js";const f=JSON.parse('{"title":"Имущество и ресурсы","description":"Учет оборудования, станков, недвижимости, транспорта и долгосрочных материальных ресурсов с учетом долей владения и амортизации.","frontmatter":{"title":"Имущество и ресурсы","description":"Учет оборудования, станков, недвижимости, транспорта и долгосрочных материальных ресурсов с учетом долей владения и амортизации.","order":19},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/property.md","filePath":"ru/docs/spaces/moy-kapital/property.md"}'),s={name:"ru/docs/spaces/moy-kapital/property.md"};function o(n,t,d,i,g,p){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="имущество-и-ресурсы" tabindex="-1">Имущество и ресурсы <a class="header-anchor" href="#имущество-и-ресурсы" aria-label="Permalink to &quot;Имущество и ресурсы&quot;">​</a></h1><p>Вкладка <strong>«Имущество и ресурсы»</strong> представляет собой материальный реестр долгосрочных физических активов мастера, которые не являются оборотным сырьем или готовой продукцией цеха: раскройные станки, швейные машины, лазерные граверы, транспортные средства, производственные и складские помещения, а также стратегические запасы редких материалов.</p><hr><h2 id="зачем-учитывать-имущество-отдельно" tabindex="-1">Зачем учитывать имущество отдельно <a class="header-anchor" href="#зачем-учитывать-имущество-отдельно" aria-label="Permalink to &quot;Зачем учитывать имущество отдельно&quot;">​</a></h2><p>В отличие от расходных материалов на складе цеха (которые списываются при выпуске изделий), дорогостоящее оборудование и недвижимость переносят свою стоимость на себестоимость продукции постепенно либо служат надежным физическим обеспечением бизнеса.</p><p>Фиксация имущества в контуре личного капитала решает три ключевые задачи:</p><ol><li><strong>Точная оценка совокупного благосостояния (Net Worth):</strong> реальная капитализация мастера включает не только деньги на счетах, но и рыночную стоимость станков, транспорта и недвижимости.</li><li><strong>Учет долевого владения:</strong> если дорогостоящий станок или лазерный плоттер куплен совместно с партнером 50/50, в системе фиксируется именно Ваша реальная доля.</li><li><strong>Контроль физического износа и амортизации:</strong> понимание остаточной стоимости оборудования позволяет заранее планировать фонды обновления парка инструментов.</li></ol><hr><h2 id="параметры-карточки-имущества" tabindex="-1">Параметры карточки имущества <a class="header-anchor" href="#параметры-карточки-имущества" aria-label="Permalink to &quot;Параметры карточки имущества&quot;">​</a></h2><p>При добавлении объекта имущества заполняются следующие поля:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Параметр</th><th style="text-align:left;">Назначение</th><th style="text-align:left;">Пример значения</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Наименование</strong></td><td style="text-align:left;">Понятное название объекта</td><td style="text-align:left;">Двоильная машина Fortuna SAS</td></tr><tr><td style="text-align:left;"><strong>Категория</strong></td><td style="text-align:left;">Тип имущества</td><td style="text-align:left;">Оборудование и станки</td></tr><tr><td style="text-align:left;"><strong>Первоначальная стоимость</strong></td><td style="text-align:left;">Затраты на покупку и пусконаладку</td><td style="text-align:left;">$350,000\\text{ ₽}$</td></tr><tr><td style="text-align:left;"><strong>Текущая рыночная оценка</strong></td><td style="text-align:left;">Справедливая цена на вторичном рынке</td><td style="text-align:left;">$310,000\\text{ ₽}$</td></tr><tr><td style="text-align:left;"><strong>Доля владения, %</strong></td><td style="text-align:left;">Процент Вашей собственности в объекте</td><td style="text-align:left;">$100%$ (или $50%$ с партнером)</td></tr><tr><td style="text-align:left;"><strong>Срок полезного использования</strong></td><td style="text-align:left;">Срок службы для расчета амортизации</td><td style="text-align:left;">$60\\text{ мес.}$ (5 лет)</td></tr><tr><td style="text-align:left;"><strong>Статус объекта</strong></td><td style="text-align:left;">Текущее состояние</td><td style="text-align:left;">В эксплуатации / В резерве / На консервации</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Математика долевого владения</p><p>Если объект находится в совместной собственности, его вклад в Ваш общий капитал рассчитывается строго пропорционально доле: $$\\text{Вклад в капитал} = \\text{Текущая стоимость} \\times \\frac{\\text{Доля владения}}{100%}$$</p></div><hr><h2 id="учет-амортизации-и-переоценка" tabindex="-1">Учет амортизации и переоценка <a class="header-anchor" href="#учет-амортизации-и-переоценка" aria-label="Permalink to &quot;Учет амортизации и переоценка&quot;">​</a></h2><p>Со временем физические активы изнашиваются, а их рыночная стоимость меняется. ОмниКрафт ЕРП позволяет поддерживать актуальность цифр двумя способами:</p><ol><li><strong>Нормативная линейная амортизация:</strong> списание стоимости равными долями на протяжении срока полезного использования.</li><li><strong>Экспертная рыночная переоценка:</strong> ручная корректировка поля «Текущая стоимость» на основе реальных предложений на рынке аналогичного оборудования (например, раз в год во время генеральной инвентаризации).</li></ol><div class="tip custom-block"><p class="custom-block-title">Ликвидность оборудования</p><p>Указывайте консервативную (ликвидационную) цену оборудования — сумму, за которую вы сможете продать станок в течение двух-трех недель в случае экстренной необходимости высвободить деньги.</p></div>',17)])])}const x=e(s,[["render",o]]);export{f as __pageData,x as default};
